    int n;
    int a[10][10];
    int zr = -1, zc = -1;

    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &a[i][j]);
            if (a[i][j] == 0) {
                zr = i;
                zc = j;
            }
        }
    }

    int magicSum = 0;

    for (int i = 0; i < n; i++) {
        int hasZero = 0;
        int sum = 0;

        for (int j = 0; j < n; j++) {
            if (a[i][j] == 0) hasZero = 1;
            sum += a[i][j];
        }

        if (!hasZero) {
            magicSum = sum;
            break;
        }
    }

    int zeroRowSum = 0;
    for (int j = 0; j < n; j++) {
        zeroRowSum += a[zr][j];
    }

    int missing = magicSum - zeroRowSum;

    printf("%d\n", missing);
    printf("%d\n", zr + 1);
    printf("%d\n", zc + 1);

    return 0;
}
